insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('academic-care-materials','academic-care-materials',true,52428800,array['application/pdf','image/jpeg','image/png','image/webp']) on conflict(id) do update set public=true,file_size_limit=52428800,allowed_mime_types=array['application/pdf','image/jpeg','image/png','image/webp'];
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('academic-care-answers','academic-care-answers',false,10485760,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=false,file_size_limit=10485760,allowed_mime_types=array['image/jpeg','image/png','image/webp'];
drop policy if exists academic_care_material_files_public_read on storage.objects;
create policy academic_care_material_files_public_read on storage.objects for select to anon,authenticated using(bucket_id='academic-care-materials');
drop policy if exists academic_care_material_files_admin_insert on storage.objects;
create policy academic_care_material_files_admin_insert on storage.objects for insert to authenticated with check(bucket_id='academic-care-materials' and public.academic_care_is_admin());
drop policy if exists academic_care_material_files_admin_update on storage.objects;
create policy academic_care_material_files_admin_update on storage.objects for update to authenticated using(bucket_id='academic-care-materials' and public.academic_care_is_admin()) with check(bucket_id='academic-care-materials' and public.academic_care_is_admin());
drop policy if exists academic_care_material_files_admin_delete on storage.objects;
create policy academic_care_material_files_admin_delete on storage.objects for delete to authenticated using(bucket_id='academic-care-materials' and public.academic_care_is_admin());
drop policy if exists academic_care_answer_files_upload on storage.objects;
create policy academic_care_answer_files_upload on storage.objects for insert to anon,authenticated with check(bucket_id='academic-care-answers' and exists(select 1 from public.academic_care_exams e where e.public_token::text=(storage.foldername(name))[1] and e.status='published' and e.exam_type in ('CQ','MCQ + CQ')));
drop policy if exists academic_care_answer_files_admin_read on storage.objects;
create policy academic_care_answer_files_admin_read on storage.objects for select to authenticated using(bucket_id='academic-care-answers' and public.academic_care_is_admin());
drop policy if exists academic_care_answer_files_admin_delete on storage.objects;
create policy academic_care_answer_files_admin_delete on storage.objects for delete to authenticated using(bucket_id='academic-care-answers' and public.academic_care_is_admin());
